<script setup lang="ts">
import{joinTypes,clubDivisions,memberTypeName}from'../membership';import{computed,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{state,refreshMine,refreshPublic}from'../store';import{api,run}from'../api';import type{Club}from'../types';import Icon from'../components/Icon.vue';import ClubCard from'../components/ClubCard.vue';import ClubProfile from'../components/ClubProfile.vue'
const route=useRoute(),router=useRouter(),query=ref(String(route.query.q||'')),category=ref('全部社团'),recruiting=ref(false),selected=ref<Club|null>(null),reason=ref(''),contact=ref(''),grade=ref(''),college=ref(''),applying=ref(false)
const joinType=ref('CLUB'),clubDivision=ref('');
const profileClub=computed(()=>state.clubs.find(c=>c.name==='征途单车俱乐部')||null)
const categories=computed(()=>['全部社团',...new Set(state.clubs.map(c=>c.category))])
const filtered=computed(()=>state.clubs.filter(c=>(category.value==='全部社团'||c.category===category.value)&&(!recruiting.value||c.recruiting)&&(!query.value||[c.name,c.summary,c.description].join('').includes(query.value))))
const membership=computed(()=>state.mine.memberships.find(m=>m.club.id===selected.value?.id))
watch(()=>route.query.q,v=>query.value=String(v||''));watch(()=>route.query.club,id=>{if(id)selected.value=state.clubs.find(c=>c.id===Number(id))||null},{immediate:true})
watch(selected,c=>{reason.value='';joinType.value=state.user?.joinType==='SOCIETY'?'SOCIETY':'CLUB';clubDivision.value='';contact.value=state.user?.contact||'';grade.value=state.user?.grade||'';college.value=state.user?.department||'';if(!c&&route.query.club)router.replace({path:'/clubs',query:{}})})
async function withdraw(){if(!membership.value)return;await run(async()=>{await api('/applications/'+membership.value!.id+'/withdraw','POST');await Promise.all([refreshMine(),refreshPublic()])},'已撤回申请或退出成员身份')}
async function apply(){if(!state.user){selected.value=null;router.push({path:'/login',query:{redirect:route.fullPath}});return}if(!reason.value.trim()||!contact.value.trim()||!grade.value.trim()||!college.value.trim())return;applying.value=true;await run(async()=>{await api(`/clubs/${selected.value!.id}/applications`,'POST',{reason:reason.value,contact:contact.value,grade:grade.value,college:college.value,joinType:joinType.value,clubDivision:joinType.value==='CLUB'?clubDivision.value:''});await Promise.all([refreshMine(),refreshPublic()]);selected.value=null},'申请已提交，请等待审核');applying.value=false}
</script>
<template><div class="page-content"><div class="page-heading"><div><div class="eyebrow">西安欧亚学院 · 征途单车俱乐部</div><h1>俱乐部展示<span class="greeting-dot">.</span></h1><p>了解征途，提交入社申请，和骑友一起出发。</p></div><span class="count-label">{{profileClub?'始于2013年世界无车日':state.clubs.length+' 个俱乐部，与你同行'}}</span></div><ClubProfile v-if="profileClub" :club="profileClub" @join="selected=profileClub"/><template v-else><div class="discovery-banner"><Icon name="bike" :size="36"/><div><h3>把热爱，骑成征途。</h3><p>西安欧亚学院征途单车俱乐部 · 骑行活动、团队协作与技能成长。</p></div><span>热爱骑行<br>安全同行 ↗</span></div><div class="filter-bar"><div class="filter-tabs"><button v-for="c in categories" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div><div class="filter-tools"><el-input v-model="query" placeholder="搜索社团名称或关键词" clearable aria-label="搜索社团"><template #prefix><Icon name="search" :size="16"/></template></el-input><el-checkbox v-model="recruiting">仅看招新</el-checkbox></div></div><div class="results-line"><span>为你找到 <b>{{filtered.length}}</b> 个社团</span><span>入社申请由俱乐部管理员审核</span></div><div class="club-grid discovery-grid"><ClubCard v-for="c in filtered" :key="c.id" :club="c" @select="selected=$event"/></div><el-empty v-if="!filtered.length" description="暂未找到匹配的社团，换个关键词试试"/></template></div>
<el-dialog class="club-detail-dialog" :model-value="!!selected" @update:model-value="(v:boolean)=>{if(!v)selected=null}" :title="selected?.name" width="min(650px, 94vw)"><template v-if="selected"><div class="detail-club-heading"><span class="club-icon large" :style="{color:selected.color,background:selected.color+'16'}"><Icon :name="selected.icon" :size="34"/></span><div><el-tag type="success" size="small">{{selected.category}}</el-tag><h3>{{selected.summary}}</h3></div></div><p class="detail-description">{{selected.description}}</p><div class="detail-facts"><span><Icon name="users"/>{{selected.memberCount}} 位成员</span><span><Icon name="pin"/>{{selected.location}}</span><span><Icon name="mail"/>{{selected.contact}}</span></div><div v-if="membership&&['PENDING','APPROVED'].includes(membership.status)" class="info-box">{{memberTypeName(membership.joinType)}} · {{membership.status==='PENDING'?'加入申请正在审核，请等待管理员处理。':'加入申请已通过，权益按当前身份生效。'}}<p>{{membership.reviewNote}}</p></div><el-form v-else-if="selected.recruiting&&state.user" @submit.prevent="apply" label-position="top"><el-form-item label="选择加入" required><el-radio-group v-model="joinType"><el-radio-button v-for="t in joinTypes" :key="t.value" :value="t.value">{{t.label}}</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="joinType==='CLUB'" label="意向部门"><select v-model="clubDivision" class="native-select"><option value="">暂未选择</option><option v-for="d in clubDivisions" :key="d" :value="d">{{d}}</option></select></el-form-item><el-form-item label="联系方式（手机 / 微信 / QQ）" required><el-input v-model="contact" maxlength="120" placeholder="请填写便于管理员联系的方式"/></el-form-item><el-form-item label="所在年级" required><el-input v-model="grade" maxlength="40" placeholder="例如：2025级"/></el-form-item><el-form-item label="所在学院" required><el-input v-model="college" maxlength="100" placeholder="例如：信息工程学院"/></el-form-item><el-form-item label="告诉我们，你为什么想加入？" required><el-input v-model="reason" type="textarea" :rows="3" maxlength="1000" show-word-limit placeholder="介绍你的骑行经历、兴趣及加入征途的期待…"/></el-form-item></el-form><div v-else-if="!selected.recruiting" class="info-box">该社团暂未开放招新，可先关注社团活动。</div></template><template #footer><el-button @click="selected=null">关闭</el-button><el-button v-if="membership&&['PENDING','APPROVED'].includes(membership.status)" type="danger" plain @click="withdraw">{{membership.status==='PENDING'?'撤回申请':'退出成员身份'}}</el-button><el-button v-if="selected?.recruiting&&!['PENDING','APPROVED'].includes(membership?.status)" type="primary" :loading="applying" :disabled="!!state.user&&(!reason.trim()||!contact.trim()||!grade.trim()||!college.trim())" @click="apply">{{state.user?'提交加入申请':'登录后申请加入'}}</el-button><el-button v-else type="primary" @click="selected=null;router.push('/center')">查看成员中心</el-button></template></el-dialog></template>
